sys_script_client.script:
function onSubmit() {
    var reqStr = g_form.getValue('requested_amount');
    var appStr = g_form.getValue('approved_amount');

    var reqAmt = parseFloat(reqStr.replace(/[^0-9.-]/g, ''));
    var appAmt = parseFloat(appStr.replace(/[^0-9.-]/g, ''));

    g_form.clearMessages();

    if (isNaN(reqAmt) || reqAmt <= 0) {
        g_form.addErrorMessage('Requested Amount must be a positive number.');
        return false;
    }

    if (appStr !== '') {
        if (isNaN(appAmt) || appAmt <= 0) {
            g_form.addErrorMessage('Approved Amount must be a positive number.');
            return false;
        }
        if (appAmt > reqAmt) {
            g_form.addErrorMessage('Approved Amount cannot exceed Requested Amount.');
            return false;
        }
    }
    return true;
}
